package io.github.diodeme.ji.extension;

import java.util.Objects;

/** Validated skill metadata and data content; deliberately has no execution callback. */
public record Skill(String name, String description, String location, String body, boolean modelInvocable) {
    public Skill {
        name = requireText(name, "skill name");
        if (name.length() > 64 || !name.matches("[a-z0-9]+(?:-[a-z0-9]+)*")) {
            throw new IllegalArgumentException("skill name must be lowercase kebab-case and at most 64 characters");
        }
        description = requireText(description, "skill description");
        if (description.length() > 1024) throw new IllegalArgumentException("skill description is too long");
        location = requireText(location, "skill location");
        Objects.requireNonNull(body, "body");
    }

    public String disclosure() {
        return name + ": " + description + " (" + location + ")";
    }

    public String expand(String arguments) {
        String suffix = arguments == null || arguments.isBlank() ? "" : "\n\nUser arguments: " + arguments.trim();
        return "<skill name=\"" + name + "\" location=\"" + location + "\">\n"
                + body.strip() + suffix + "\n</skill>";
    }

    private static String requireText(String value, String label) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(label + " must not be blank");
        return value;
    }
}
